package com.muxigame.city;

import java.util.*;
import java.nio.file.*;
import net.minecraft.core.BlockPos;
import net.minecraft.gametest.framework.*;
import net.minecraft.nbt.*;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.level.GameType;
import net.minecraft.world.level.storage.LevelResource;
import net.neoforged.neoforge.gametest.*;

@GameTestHolder(CityMod.ID) @PrefixGameTestTemplate(false)
public final class CityTestsTownSetup {
 @GameTest(template="empty") public static void dedicatedServerDispatchAndPausedRegistration(GameTestHelper h){try(var f=new Fixture(h)){net.neoforged.neoforge.network.registration.NetworkRegistry.configureMockConnection(f.player.connection.getConnection());String initial=f.state();var read=f.request("townview",f.city,true,null);CityMod.request(f.player,read);h.assertTrue(initial.equals(f.state()),"Normal packet dispatch can read a blank town on dedicated server without loading client screens");CityMod.request(f.player,f.request("townregister",f.city,true,null));h.assertTrue(f.trade.state.towns.containsKey(f.city.id)&&!RuralSettlement.active(f.player.server,f.city.id),"Actual dispatch registers and acknowledges without starting simulation");String before=f.state();CityMod.request(f.player,f.request("townregister",f.city,true,null));h.assertTrue(before.equals(f.state()),"Duplicate request returns failure without mutation");f.city.revision++;CityMod.request(f.player,read);h.assertTrue(before.equals(f.state()),"Refresh can recover from stale city revision without a write");}h.succeed();}
 @GameTest(template="empty") public static void runningObservationAndMissingPeerRejectBeforeWrite(GameTestHelper h){try(var f=new Fixture(h)){boolean running=f.trade.state.run.running;try{f.trade.state.run.running=true;f.reject(f.request("townregister",f.city,true,null),"Registration cannot alter an automated run's universe");}finally{f.trade.state.run.running=running;}var r=f.request("townregister",f.city,true,null);var form=CityEconomy.JSON.fromJson(r.value(),CityTownSetup.Form.class);form.partner=UUID.randomUUID().toString();f.reject(new CityNetwork.Request(r.op(),r.city(),r.revision(),0,0,0,0,0,0,CityEconomy.JSON.toJson(form),false),"Failed peer validation never partially registers the local city");}h.succeed();}
 static final class AccessPlayer extends ServerPlayer {
  boolean creative=true,operator;
  AccessPlayer(GameTestHelper h){super(h.getLevel().getServer(),h.getLevel(),new com.mojang.authlib.GameProfile(UUID.randomUUID(),"town-access"),net.minecraft.server.level.ClientInformation.createDefault());}
  @Override public boolean hasPermissions(int level){return operator;}
  @Override public boolean isCreative(){return creative;}
 }
 static final class Fixture implements AutoCloseable {
  final GameTestHelper h;final ServerPlayer player;final CityTrade trade;final CityData.City city,village,other;final long revision;
  Fixture(GameTestHelper h){this(h,false);}
  Fixture(GameTestHelper h,boolean access){this.h=h;player=access?new AccessPlayer(h):h.makeMockServerPlayerInLevel();if(!access)player.setGameMode(GameType.CREATIVE);var data=CityData.get(player.server);var pos=h.absolutePos(new BlockPos(1,1,1));String dim=h.getLevel().dimension().location().toString();city=data.create(player.getUUID(),"登记城",dim,CityBounds.between(pos,pos.offset(3,3,3)));village=data.create(player.getUUID(),"登记村",dim,CityBounds.between(pos.east(8),pos.offset(11,3,3)));other=data.create(player.getUUID(),"其他城",dim,CityBounds.between(pos.east(16),pos.offset(19,3,3)));trade=CityTrade.get(player.server);revision=trade.state.registrationRevision;}
  CityNetwork.Request request(String op,CityData.City c,boolean urban,CityData.City peer){var form=new CityTownSetup.Form();form.revision=trade.state.registrationRevision;form.urban=urban;if(peer!=null){form.partner=peer.id.toString();form.partnerRevision=peer.revision;}return new CityNetwork.Request(op,c.id.toString(),c.revision,0,0,0,0,0,0,CityEconomy.JSON.toJson(form),false);}
  void register(CityData.City c,boolean urban){CityTownSetup.apply(player,request("townregister",c,urban,null));}
  String state(){return CityEconomy.JSON.toJson(trade.state);}
  void reject(CityNetwork.Request request,String reason){String before=state();boolean refused=false;try{CityTownSetup.apply(player,request);}catch(RuntimeException e){refused=true;}h.assertTrue(refused&&before.equals(state()),reason);}
  public void close(){for(var c:List.of(city,village,other)){trade.state.towns.remove(c.id);trade.state.businesses.values().removeIf(b->c.id.equals(b.city));CityData.get(player.server).cities.remove(c.id);}trade.state.registrationRevision=revision;}
 }
 @GameTest(template="empty") public static void normalRegistrationIsZeroAssetAndDoesNotStart(GameTestHelper h){try(var f=new Fixture(h)){var s=f.player.server;String money=CityEconomy.JSON.toJson(CityEconomy.get(s).state),rural=CityEconomy.JSON.toJson(RuralSettlement.get(s).state),houses=CityEconomy.JSON.toJson(f.city.housing),works=CityEconomy.JSON.toJson(f.city.works),run=CityEconomy.JSON.toJson(f.trade.state.run);var terrain=h.getLevel().getBlockState(h.absolutePos(new BlockPos(1,1,1)));var config=CityEconomy.JSON.toJson(f.trade.state.config);f.register(f.city,true);var t=f.trade.state.towns.get(f.city.id);h.assertTrue(t!=null&&t.urban&&t.model&&t.partner==null,"Blank normal city gets finite economy without sample initialization");h.assertTrue(money.equals(CityEconomy.JSON.toJson(CityEconomy.get(s).state))&&rural.equals(CityEconomy.JSON.toJson(RuralSettlement.get(s).state))&&houses.equals(CityEconomy.JSON.toJson(f.city.housing))&&works.equals(CityEconomy.JSON.toJson(f.city.works))&&run.equals(CityEconomy.JSON.toJson(f.trade.state.run))&&config.equals(CityEconomy.JSON.toJson(f.trade.state.config))&&terrain.equals(h.getLevel().getBlockState(h.absolutePos(new BlockPos(1,1,1)))),"Registration changes only town metadata: no people, money, food, blocks, supply, wages, policy or automatic start");h.assertTrue(CityRoute.village(f.trade,f.city.id)==null,"Unlinked new city never falls back to an old sample village");}h.succeed();}
 @GameTest(template="empty") public static void newTownUnlocksNormalBakerPreflight(GameTestHelper h){try(var f=new CityTestsCityWorks.Fixture(h)){var p=h.makeMockServerPlayerInLevel();p.setGameMode(GameType.CREATIVE);p.setUUID(f.city.owner);CityTestsNpcDesigner.site(f,"baker");var a=CityTestsNpcDesigner.actor(f,UUID.randomUUID());var t=CityNpcDesigner.defaults(RuralRules.Role.BAKER);boolean missing=false;try{CityNpcDesigner.preflight(f.server,f.city,a,a.blockPosition(),t);}catch(IllegalArgumentException e){missing=e.getMessage().contains("城村经济登记");}h.assertTrue(missing,"Before registration normal career creation clearly names the missing setup");var form=new CityTownSetup.Form();var trade=CityTrade.get(f.server);form.revision=trade.state.registrationRevision;form.urban=true;try{CityTownSetup.apply(p,new CityNetwork.Request("townregister",f.city.id.toString(),f.city.revision,0,0,0,0,0,0,CityEconomy.JSON.toJson(form),false));long money=f.money();CityNpcDesigner.apply(f.server,f.city,a,t);h.assertTrue(trade.state.businesses.values().stream().anyMatch(b->b.worker.equals(a.getUUID())&&b.kind.equals("baker"))&&f.money()==money,"Same normal town now creates a working baker registration with zero gifted capital");}finally{trade.state.businesses.values().removeIf(b->f.city.id.equals(b.city));trade.state.towns.remove(f.city.id);}}h.succeed();}
 @GameTest(template="empty") public static void oppositeTownLinkPersistsOnDisk(GameTestHelper h)throws Exception{try(var f=new Fixture(h)){f.register(f.city,true);f.register(f.village,false);CityTownSetup.apply(f.player,f.request("townlink",f.city,true,f.village));Path path=f.player.server.getWorldPath(LevelResource.ROOT).resolve("city-town-registration-"+f.city.id+".nbt");try{NbtIo.writeCompressed(f.trade.save(new CompoundTag(),h.getLevel().registryAccess()),path);var loaded=CityTrade.load(NbtIo.readCompressed(path,NbtAccounter.create(32L*1024*1024)),h.getLevel().registryAccess());h.assertTrue(loaded.state.towns.get(f.city.id).partner.equals(f.village.id)&&loaded.state.towns.get(f.village.id).partner.equals(f.city.id)&&loaded.state.towns.get(f.city.id).model&&loaded.state.registrationRevision==f.trade.state.registrationRevision,"Real compressed SavedData save/load preserves reciprocal routing, type and edit revision");}finally{Files.deleteIfExists(path);}}h.succeed();}
 @GameTest(template="empty") public static void duplicateAndStaleRegistrationNeverResetState(GameTestHelper h){try(var f=new Fixture(h)){var stale=f.request("townregister",f.village,false,null);f.register(f.city,true);f.reject(f.request("townregister",f.city,true,null),"Duplicate type registration cannot clear inventory or business state");f.reject(stale,"Stale global registration revision is rejected without changes");var next=f.request("townregister",f.other,true,null);f.other.revision++;f.reject(next,"Stale city revision cannot initialize");}h.succeed();}
 @GameTest(template="empty") public static void invalidRoutesCannotWriteEitherTown(GameTestHelper h){try(var f=new Fixture(h)){f.register(f.city,true);f.register(f.village,false);f.register(f.other,true);f.reject(f.request("townlink",f.city,true,f.city),"Self-link rejected");f.reject(f.request("townlink",f.city,true,f.other),"Same-type links rejected");CityTownSetup.apply(f.player,f.request("townlink",f.city,true,f.village));f.reject(f.request("townlink",f.other,true,f.village),"Cannot steal another town route");f.reject(f.request("townlink",f.city,false,f.other),"Cannot change town type using a forged link request");}h.succeed();}
 @GameTest(template="empty") public static void unknownUnregisteredAndCrossDimensionPeersRejectAtomically(GameTestHelper h){try(var f=new Fixture(h)){f.register(f.city,true);f.reject(f.request("townlink",f.city,true,f.village),"Unregistered peer is not implicitly initialized");f.register(f.village,false);String dim=f.village.dimension;CityData.get(f.player.server).cities.put(f.village.id,new CityData.City(f.village.id,f.village.owner,f.village.name,"minecraft:the_nether",f.village.bounds));f.reject(f.request("townlink",f.city,true,f.village),"Cross-dimension peer rejected before mutation");CityData.get(f.player.server).cities.put(f.village.id,f.village);var r=f.request("townregister",f.other,true,null);f.reject(new CityNetwork.Request(r.op(),UUID.randomUUID().toString(),r.revision(),0,0,0,0,0,0,r.value(),false),"Nonexistent city rejected");f.reject(f.request("townunknown",f.city,true,null),"Unknown operation rejected");}h.succeed();}
 @GameTest(template="empty") public static void permissionsApplyToBothEnds(GameTestHelper h){try(var f=new Fixture(h,true)){var actor=(AccessPlayer)f.player;actor.creative=false;f.reject(f.request("townregister",f.city,true,null),"Survival non-OP cannot initialize even their own town");actor.creative=true;f.register(f.city,true);f.register(f.village,false);CityData.get(f.player.server).cities.put(f.village.id,new CityData.City(f.village.id,UUID.randomUUID(),f.village.name,f.village.dimension,f.village.bounds));f.reject(f.request("townlink",f.city,true,f.village),"Creative non-OP cannot modify another owner's peer");CityData.get(f.player.server).cities.put(f.other.id,new CityData.City(f.other.id,UUID.randomUUID(),f.other.name,f.other.dimension,f.other.bounds));f.reject(f.request("townregister",f.other,true,null),"Creative ownership check applies to current city");actor.operator=true;actor.creative=false;CityTownSetup.apply(actor,f.request("townlink",f.city,true,f.village));h.assertTrue(f.trade.state.towns.get(f.city.id).partner.equals(f.village.id),"Survival OP may authorize both sides; permission is independent of creative mode");}h.succeed();}
 @GameTest(template="empty") public static void viewIsReadOnlyAndLegacyDataStillLoads(GameTestHelper h){try(var f=new Fixture(h)){String before=f.state();var view=CityTownSetup.view(f.player,f.city,"");h.assertTrue(!view.getBoolean("Registered")&&before.equals(f.state()),"Viewing does not create an economic town");var tag=f.trade.save(new CompoundTag(),h.getLevel().registryAccess());var json=com.google.gson.JsonParser.parseString(new String(tag.getByteArray("Json"),java.nio.charset.StandardCharsets.UTF_8)).getAsJsonObject();json.remove("registrationRevision");tag.putByteArray("Json",json.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));h.assertTrue(CityTrade.load(tag,h.getLevel().registryAccess()).state.registrationRevision==0,"Schema1 saves before registration UI load with revision0; no reset or migration of assets");}h.succeed();}
}
